#!/usr/bin/env bash
set -u
echo "== 解包 NISP一级题库 =="
mkdir -p /tmp/xm-nisp && rm -rf /tmp/xm-nisp/site && mkdir -p /tmp/xm-nisp/site
echo '' | base64 -d > /tmp/xm-nisp/u.tgz
tar -xzf /tmp/xm-nisp/u.tgz -C /tmp/xm-nisp/site
echo "== 覆盖到站点 =="
sudo cp -r /tmp/xm-nisp/site/. /var/www/xinmo-site/
echo "== 校验 =="
ls -l /var/www/xinmo-site/resources/nisp-level1-quiz/index.html
grep -c 'nisp-level1-quiz' /var/www/xinmo-site/assets/js/resources.js
echo "== DONE =="
